import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, normalizeId, validateCustomer, mergeCustomers } from '../src/customers.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('getCustomer finds a customer by id', () => {
  const result = getCustomer('C-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer reports an unknown id', () => {
  const result = getCustomer('C-999');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('every customer has a tier', () => {
  const result = getCustomer('C-001');
  assert.ok(result.value.tier);
  assert.ok(['gold', 'silver', 'standard'].includes(result.value.tier));
});

test('validateCustomer needs an id, a name and an email', () => {
  const bad = [
    {},
    { id: 'C-1' },
    { id: 'C-1', name: 'Name' },
    { id: 'C-1', name: 'Name', email: 'invalid' },
    { id: '', name: 'Name', email: 'name@example.com' },
  ];

  bad.forEach((c) => {
    assert.equal(validateCustomer(c).ok, false);
  });

  const good = { id: 'C-1', name: 'Name', email: 'name@example.com' };
  assert.equal(validateCustomer(good).ok, true);
});

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId(' c-007 '), 'C-007');
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-007'), 'C-007');
});

test('normalizeId handles mixed case and spaces', () => {
  assert.equal(normalizeId(' c-007 '), 'C-007');
});

test('getCustomer finds customer with normalized ID', () => {
  const result = getCustomer('c-001');
  assert.equal(result.ok, true);
});

test('getCustomer finds customer with spaces', () => {
  const result = getCustomer(' C-001 ');
  assert.equal(result.ok, true);
});

test('getCustomer finds customer with lowercase and spaces', () => {
  const result = getCustomer(' c-001 ');
  assert.equal(result.ok, true);
});

test('mergeCustomers successfully merges two customers', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
});

test('mergeCustomers updates invoices belonging to fromId', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv = issueInvoice(inv.value, []).value;

  const result = mergeCustomers(customers, [inv], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND if fromId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  const result = mergeCustomers(customers, [], 'C-999', 'C-002');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND if intoId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-999');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers returns SAME_CUSTOMER if both ids are the same', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-001');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers handles case insensitivity for SAME_CUSTOMER check', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
  ];

  const result = mergeCustomers(customers, [], 'c-001', 'C-001');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers with multiple invoices from fromId', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  let inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 50 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result = mergeCustomers(customers, [inv1, inv2], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers with mixed invoices (some from fromId, some from others)', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
    { id: 'C-003', name: 'Third', email: 'third@example.com', tier: 'silver' },
  ];

  let inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 50 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result = mergeCustomers(customers, [inv1, inv2], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers does not mutate original customers array', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];
  const originalLength = customers.length;

  mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(customers.length, originalLength);
  assert.ok(customers.some((c) => c.id === 'C-001'));
});

test('mergeCustomers does not mutate original invoices array', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv = issueInvoice(inv.value, []).value;

  const invoices = [inv];
  const originalCustomerId = invoices[0].customerId;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(invoices[0].customerId, originalCustomerId);
});

test('mergeCustomers with empty invoice list', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.customers.length, 1);
});

test('mergeCustomers with no invoices belonging to fromId', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
    { id: 'C-003', name: 'Third', email: 'third@example.com', tier: 'silver' },
  ];

  let inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv = issueInvoice(inv.value, []).value;

  const result = mergeCustomers(customers, [inv], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-003');
});

test('mergeCustomers handles normalized IDs consistently', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  let inv = createInvoice({
    customerId: 'c-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv = issueInvoice(inv.value, []).value;

  const result = mergeCustomers(customers, [inv], ' c-001 ', ' C-002 ');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers returns ok/error structure', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.ok('ok' in result);
  assert.ok('value' in result || 'error' in result);
});

test('mergeCustomers preserves customer properties', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold', country: 'NL' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard', country: 'US' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  const intoCustomer = result.value.customers.find((c) => c.id === 'C-002');
  assert.equal(intoCustomer.name, 'Second');
  assert.equal(intoCustomer.tier, 'standard');
  assert.equal(intoCustomer.country, 'US');
});

test('mergeCustomers with three customers, merge first into second', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
    { id: 'C-003', name: 'Third', email: 'third@example.com', tier: 'silver' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
