    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  const result = mergeCustomers(customers, [], 'C-001', 'C-001');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers handles case insensitivity for SAME_CUSTOMER check', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
  ];

  const result = mergeCustomers(customers, [], 'c-001', 'C-001');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers with multiple invoices from fromId', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  let inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 50 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result = mergeCustomers(customers, [inv1, inv2], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers with mixed invoices (some from fromId, some from others)', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
    { id: 'C-003', name: 'Third', email: 'third@example.com', tier: 'silver' },
  ];

  let inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 50 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result = mergeCustomers(customers, [inv1, inv2], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers does not mutate original customers array', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];
  const originalLength = customers.length;

  mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(customers.length, originalLength);
  assert.ok(customers.some((c) => c.id === 'C-001'));
});

test('mergeCustomers does not mutate original invoices array', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Second', email: 'second@example.com', tier: 'standard' },
  ];

  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv = issueInvoice(inv.value, []).value;

  const invoices = [inv];
  const originalCustomerId = invoices[0].customerId;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(invoices[0].customerId, originalCustomerId);
});

test('mergeCustomers with empty invoice list', () => {
  const customers = [
    { id: 'C-001', name: 'First', email: 'first@example.com', tier: 'gold' },
